ST.xhtml:p:
Rtring_Stop(CLK := g_NCMoveData.NCAXISCMD[IndexValue].NCAxisStop);
IF Rtring_Stop.Q THEN
	nStopState := 10;
    StopDone:=FALSE;
END_IF;
CASE nStopState OF
  0:
	nStopState := 0;
  10:
	NCAxisStop(
     EXECUTE := g_NCMoveData.NCAXISCMD[IndexValue].NCAxisStop(*BOOL*),
     AXIS :=NCAxisName^(*AXIS_REF*),
     OUTAXIS =>NCAxisName^ (*AXIS_REF*));
     IF NCAxisStop.Done  THEN
		g_NCMoveData.NCAXISCMD[IndexValue].NCAxisStop:= FALSE;
        StopDone:=TRUE;
    END_IF;
    IF NCAxisStop.CommandAborted OR NCAxisStop.Error THEN
      g_NCMoveData.NCAXISCMD[IndexValue].NCAxisStop := FALSE;
    END_IF;


END_CASE;

ERRORID := NCAxisStop.ERRORID;
